function summarizeRow(updated, before, block, sheet, config, timestamp) {
  const expected = block + "\n\n" + before.raw;
  if (
    updated.raw !== expected ||
    updated.excerpt !== before.excerpt ||
    updated.status !== before.status ||
    updated.protected ||
    updated.title !== before.title ||
    updated.link !== before.link
  ) {
    throw new Error(
      "WordPress did not confirm the exact new block and preserved original article.",
    );
  }
  const id = String(updated.id);
  const date = timestamp || new Date().toISOString();
  const title = updated.title
    .replace(/<[^>]*>/g, "")
    .replace(/\s+/g, " ")
    .trim();
  const edit = config.site + "/wp-admin/post.php?post=" + id + "&action=edit";
  const row = {
    post_id: id,
    summary: block,
    post_link: updated.link,
    edit_link: edit,
    title,
    summary_date: date,
    summarized_date: date,
  };
  const word = title
    .replace(/[<>&*_`~|]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const text = [
    "WordPress post updated with an AI summary",
    word,
    "Post ID: " + id,
    "Article: <" + updated.link + ">",
    "Edit: <" + edit + ">",
  ]
    .filter(Boolean)
    .join("\n");
  return { id, values: sheet.headers.map((key) => row[key]), text };
}

const { id, config, sheet, before, block } = $("Confirm the updated article").itemMatching(0).json;
const row = summarizeRow(
  editablePost($input.first().json, id, config.origin),
  before,
  block,
  sheet,
  config,
);
return [{ json: { id, config, row }, pairedItem: { item: 0 } }];

function confirmSummaryLog(receipt, row, settings) {
  const { spreadsheetId, updatedRows, updatedRange, updatedData } = receipt ?? {};
  if (
    spreadsheetId !== settings.spreadsheet ||
    updatedRows !== 1 ||
    typeof updatedRange !== "string" ||
    !updatedRange.replace(/^'([^']+)'!/, "$1!").startsWith(settings.tab + "!") ||
    updatedData?.values?.length !== 1 ||
    JSON.stringify(updatedData.values[0]) !== JSON.stringify(row.values)
  ) {
    throw new Error(
      "Sheets did not confirm the exact post summary row. Before retrying, inspect the post and the worksheet.",
    );
  }
}

const { id, config, row } = $("Confirm the matching worksheet row").itemMatching(0).json;
const receipt = $input.first().json;
confirmSummaryLog({ spreadsheetId: receipt.spreadsheetId, ...receipt.updates }, row, config);
return [{ json: { id, channel: config.channel, text: row.text }, pairedItem: { item: 0 } }];

const { id, channel } = $("Verify the summary log row").itemMatching(0).json;
const result = $input.first().json;
if (result.ok !== true || result.channel !== channel || !/^\d+\.\d+$/.test(result.ts))
  throw Error("Slack did not confirm the article notification.");
return [
  { json: { postId: id, state: "completed", channel, ts: result.ts }, pairedItem: { item: 0 } },
];
